// Uma passada por FONTE de Cost Report (spec.md 3.1.5, decisao de 09/09).
//
// O ciclo completo — leitura, checagem de contrato, escrita e as DUAS camadas de
// confirmacao — roda por inteiro para uma fonte antes de comecar a proxima. Por isso
// este node emite um item por fonte e o "Execute Workflow" abaixo usa mode=each: cada
// item vira uma execucao separada do workflow da Fase 1, uma depois da outra.
//
// Por que isso importa: os numeros de linha se repetem entre as duas planilhas (a celula
// N293 existe nas duas, sao arquivos independentes). Conferir as duas listas de mudancas
// contra um unico arquivo aberto abortava a execucao por divergencia espuria — ou, pior,
// dava falso positivo, confirmando uma escrita que nunca aconteceu na outra fonte.
//
// A ordem e deliberada: S01 primeiro (AREP + Reunion, o volume maior), S02 depois.
return [
  { json: { fonteId: 'S01', descricao: 'Cost Report S01 — AREP + Reunion' } },
  { json: { fonteId: 'S02', descricao: 'Cost Report S02 — Soft Pré' } },
];

// Resumo do despacho. Cada sub-execucao ja manda o proprio relatorio no Telegram
// (spec 7.3) e grava a propria entrada no log_diario — este node so consolida o que
// aconteceu no nivel do despachante, pra ficar visivel na tela de execucao.
const fontes = $('Definir fontes a processar').all().map((i) => i.json.fonteId);
return [{ json: { despachadas: fontes, total: fontes.length, quando: new Date().toISOString() } }];
